function applyServerGate(open){serverOpen=!!open;const gate=$('#serverGate');if(gate)gate.classList.add('hidden');const start=$('#startBtn');if(start)start.disabled=false;}
async function syncServerGate(){try{const r=await fetch('/api/server-status',{cache:'no-store'});if(!r.ok)return;const j=await r.json();applyServerGate(!!j.open)}catch{}}
async function startAssessment(){
 message('');const studentId=$('#studentId').value.trim(),name=$('#studentName').value.trim();
 try{
  const r=await fetch('/api/start',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({studentId,name})});const j=await r.json();if(!r.ok)throw new Error(j.error||'시작 오류');
  session=j.session;initState();step=Number.isInteger(state.currentStep)?Math.min(3,Math.max(0,state.currentStep)):0;if(j.resumed&&!state.countryRevealDone&&(Number(session.progress||0)>0||step>0||state.priority1)){state.countryRevealDone=true}
  $('#login').classList.add('hidden');$('#timer').classList.remove('hidden');$('#glossaryBtn').classList.remove('hidden');$('#countryGuideBtn').classList.remove('hidden');
  applyTimerState(j.timer||{});startTimer();
  if(session.status==='review_reopened'){state.countryRevealDone=true;state.reviewReady=true;$('#decisionReviewBtn').classList.remove('hidden');showFinalReview();toast('교사가 최종 검토 화면을 다시 열었습니다. 필요한 부분을 수정한 뒤 다시 제출하세요.');}
  else if(!state.countryRevealDone){showCountryAssignment()}
  else if(state.preparationComplete&&timerPhase==='ready'){showPreStartWait()}
  else if(state.reviewReady){$('#decisionReviewBtn').classList.remove('hidden');showFinalReview()}
  else{$('#decisionReviewBtn').classList.remove('hidden');showAssessment();render()}
  if(j.resumed)toast('이전 진행 내용을 불러왔습니다.');
 }catch(e){alert(e.message)}
}
function allCountryOverview(){const intro={hanbit:'책임과 기술력은 크지만 산업과 일자리를 지켜야 합니다.',saebom:'발전이 필요하지만 석탄 사용과 배출도 줄여야 합니다.',pureun:'배출 책임은 작지만 해수면 상승 피해가 매우 큽니다.',taeyang:'석유 산업을 유지하면서 친환경 산업으로 바꿔야 합니다.'};return `<div class="country-overview-grid">${Object.entries(countryData).map(([k,c])=>`<article class="country-overview-card ${state.countryRevealDone&&session?.country===k?'my-country':''}">${state.countryRevealDone&&session?.country===k?'<span class="my-country-badge">내 국가</span>':''}<div class="country-overview-head"><span class="country-symbol">${{hanbit:'🏭',saebom:'🏗️',pureun:'🌊',taeyang:'☀️'}[k]}</span><div><h3>${c.name}</h3><span>${c.type}</span></div></div><p>${intro[k]}</p><div class="country-overview-points"><b>회의에서 해결할 문제</b><span>${c.dilemma}</span></div></article>`).join('')}</div>`}
function showCountryAssignment(){
 $('#assessment').classList.add('hidden');$('#finalReview').classList.add('hidden');$('#preStartWait').classList.add('hidden');$('#countryAssign').classList.remove('hidden');$('#decisionReviewBtn').classList.add('hidden');$('#progress').style.width='3%';$('#lessonPill').textContent='국가 배정 · 수행 준비';
 $('#countryIntroGrid').innerHTML=allCountryOverview();
 if(state.countryRevealDone){showAssignedCountryResult()}else{$('#rouletteResult').classList.add('hidden');$('#spinCountryBtn').classList.remove('hidden')}
}
function showAssignedCountryResult(){
 const c=countryData[session.country];$('#countryIntroGrid').innerHTML=allCountryOverview();$('#rouletteResult').classList.remove('hidden');$('#assignedCountryName').textContent=c.name;$('#assignedCountryType').textContent=c.type;$('#assignedCountryStory').textContent=c.story;$('#assignedCountryStrength').textContent=c.facts[2];$('#assignedCountryWorry').textContent=c.dilemma;$('#assignedCountryMission').textContent=`국제회의에서 ${c.name}의 상황을 지키면서 다른 국가도 받아들일 수 있는 합의를 만드세요.`;$('#assignedCountryDilemma').textContent=`핵심 과제 · ${c.dilemma}`;$('#spinCountryBtn').classList.add('hidden');
}
async function spinCountryRoulette(){
 const btn=$('#spinCountryBtn'),wheel=$('#rouletteWheel');if(btn.disabled)return;btn.disabled=true;btn.textContent='국가를 배정하고 있습니다…';
 const idx=['hanbit','saebom','pureun','taeyang'].indexOf(session.country);const target=1440+(315-idx*90);wheel.style.transition='transform 2.8s cubic-bezier(.15,.72,.12,1)';wheel.style.transform=`rotate(${target}deg)`;
 setTimeout(async()=>{state.countryRevealDone=true;await savePreparation(false);showAssignedCountryResult();toast(`${countryLabels[session.country]} 대표로 배정되었습니다.`)},2900)
}
async function savePreparation(complete=true){if(!session)return false;state.countryRevealDone=true;if(complete)state.preparationComplete=true;try{const r=await fetch('/api/preparation',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:session.sessionId,countryRevealDone:true,preparationComplete:!!state.preparationComplete})});if(!r.ok)throw new Error();return true}catch{toast('준비 상태 저장에 실패했습니다. 인터넷 연결을 확인하세요.');return false}}
function showPreStartWait(){waitingForClassStart=true;$('#countryAssign').classList.add('hidden');$('#assessment').classList.add('hidden');$('#finalReview').classList.add('hidden');$('#preStartWait').classList.remove('hidden');$('#decisionReviewBtn').classList.add('hidden');$('#progress').style.width='5%';$('#lessonPill').textContent='국가 배정 완료 · 수행 시작 대기';$('#waitingCountrySummary').innerHTML=`<span>${countryLabels[session.country]}</span><small>${countryData[session.country].type}</small>`;window.scrollTo({top:0,behavior:'smooth'})}
async function beginAssignedAssessment(){state.countryRevealDone=true;state.preparationComplete=true;const saved=await savePreparation(true);if(!saved)return;if(timerPhase==='running'){waitingForClassStart=false;$('#countryAssign').classList.add('hidden');$('#decisionReviewBtn').classList.remove('hidden');showAssessment();render();window.scrollTo({top:0,behavior:'smooth'});return}showPreStartWait()}
function handleClassStartTransition(){if(!waitingForClassStart||timerPhase!=='running')return;waitingForClassStart=false;$('#preStartWait').classList.add('hidden');$('#decisionReviewBtn').classList.remove('hidden');showAssessment();render();toast('수행이 시작되었습니다. 지금부터 45분입니다.');window.scrollTo({top:0,behavior:'smooth'})}
function applyTimerState(t={}){timerExempt=!!t.exempt;timerPhase=String(t.phase||'');if(typeof t.serverOpen==='boolean')applyServerGate(t.serverOpen);timerPaused=!!t.paused||!serverOpen;if(Number.isFinite(Number(t.remainingSeconds)))remaining=Math.max(0,Number(t.remainingSeconds));updateTimer()}
async function syncTimer(){if(!session)return;try{const r=await fetch(`/api/timer/${session.sessionId}`,{cache:'no-store'});if(!r.ok)return;applyTimerState(await r.json());handleClassStartTransition();if(!timerExempt&&remaining<=0&&!autoSubmitting)autoSubmitOnTime()}catch{}}
function startTimer(){clearInterval(timerHandle);clearInterval(timerSyncHandle);updateTimer();timerHandle=setInterval(()=>{if(timerExempt||timerPaused)return;if(remaining>0)remaining--;updateTimer();if(remaining===10*60)toast('남은 수행 활동 시간이 10분입니다.');if(remaining===5*60)toast('5분 남았습니다. 최종 판단과 제출을 확인하세요.');if(remaining<=0&&!autoSubmitting)autoSubmitOnTime()},1000);timerSyncHandle=setInterval(syncTimer,5000);syncTimer()}
function updateTimer(){const el=$('#timer');if(timerExempt){el.textContent='수정 허용';el.classList.remove('urgent');el.classList.add('paused');return}const m=Math.floor(Math.max(0,remaining)/60),s=Math.max(0,remaining)%60;el.textContent=timerPaused?`⏸ ${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`:`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const phaseMessage={ready:'선생님이 수행을 시작하면 시간이 시작됩니다.',paused:'선생님이 수행을 일시정지했습니다. 답안은 보존됩니다.',finished:'45분 수행시간이 종료되었습니다.'};el.title=timerPaused?(phaseMessage[timerPhase]||'수행평가 시간이 일시정지되어 있습니다.'):'';el.classList.toggle('paused',timerPaused);el.classList.toggle('urgent',!timerPaused&&remaining<=600)}
async function autoSubmitOnTime(){if(autoSubmitting||timerExempt)return;autoSubmitting=true;collect();state.timeExpired=true;await save(false);await finalSubmit(true)}
function showAssessment(){$('#finalReview').classList.add('hidden');$('#preStartWait').classList.add('hidden');$('#assessment').classList.remove('hidden')}
function render(){
 message('');$('#progress').style.width=`${stepProgress[step]}%`;$('#prevBtn').style.visibility=step===0?'hidden':'visible';$('#nextBtn').textContent=step===3?'최종 검토 →':'다음 단계 →';
 const stages=['국가와 처음 판단','핵심 딜레마와 정책 선택','상대국과 절충','판단 변화와 최종 합의'];$('#lessonPill').textContent='45분 수행평가 · 학생 활동 약 30분';$('#lessonHeader').innerHTML=`<span class="phase-badge">STEP ${step+1} / 4</span><b>${stages[step]}</b><span>선택은 간단하게, 이유는 핵심만 작성하세요.</span>`;
 const funcs=[renderFastCountry,renderFastDilemma,renderFastCompromise,renderFastReflection];$('#stepHost').innerHTML=funcs[step]();bindStep();
 ensureReviewReturnButton();
}
function countryCard(full=true){const c=countryData[session.country];return `<div class="country-card my-country"><span class="my-country-badge">내 국가</span><div class="eyebrow">당신이 대표하는 국가</div><h3>${c.name}</h3><div><span class="tag">${c.type}</span>${c.tags.map(x=>`<span class="tag">${x}</span>`).join('')}</div><p class="country-story">${c.story}</p>${full?`<div class="facts">${c.facts.map(x=>`<div class="fact">${x}</div>`).join('')}</div>`:''}<div class="dilemma">핵심 딜레마 · ${c.dilemma}</div></div>`}
function bar(value){return `<div class="bar-track"><div class="bar-fill" style="width:${value}%"></div></div><span class="metric-num">${value}</span>`}
function metricTable(type){const labels=type==='responsibility'?[['past','과거 누적 배출 책임'],['current','현재 배출 수준']]:type==='vulnerability'?[['damage','기후피해 위험']]:[['fossil','화석연료 의존'],['transition','친환경 전환 역량']];return `<div class="metric-table">${Object.entries(countryData).map(([k,c])=>`<div class="metric-country ${state.countryRevealDone&&session?.country===k?'my-country':''}">${state.countryRevealDone&&session?.country===k?'<span class="my-country-badge compact">내 국가</span>':''}<b>${c.name}</b>${labels.map(([m,l])=>`<div class="metric-line"><span>${l}</span>${bar(c.metrics[m])}</div>`).join('')}<div class="metric-why"><b>배경</b> ${c.metricNotes[type]}</div></div>`).join('')}</div>`}
function renderEvidence(){return `<div class="step-title"><span class="step-num">1</span><h2>자료를 읽고 우리 국가의 조건을 파악하세요</h2></div><p class="sub">네 나라는 모두 가상국가입니다. 앞에서 확인한 경제·산업·에너지 배경 때문에 아래 지표가 서로 다르게 나타납니다. <b>숫자만 보지 말고 각 나라의 배경 설명과 함께 읽으세요.</b></p>${countryCard(true)}<div class="notice soft"><b>다른 나라가 기억나지 않나요?</b> 상단의 <b>‘4개국 배경’</b> 버튼을 누르면 언제든 한빛국·새봄국·푸른섬국·태양국의 배경을 다시 확인할 수 있습니다.</div><div class="evidence-grid"><div class="source-card"><span class="source-no">자료 1</span><h3>배출 책임</h3><p>과거 산업화 과정에서 누적된 책임과 현재 배출 수준을 비교합니다. 각 나라가 왜 이런 수치를 보이는지도 함께 확인하세요.</p>${metricTable('responsibility')}</div><div class="source-card"><span class="source-no">자료 2</span><h3>기후피해 위험</h3><p>지리적 조건과 대응 능력을 고려했을 때 기후재난으로 직접 피해를 받을 가능성을 비교합니다.</p>${metricTable('vulnerability')}</div><div class="source-card"><span class="source-no">자료 3</span><h3>에너지·전환 조건</h3><p>현재 화석연료에 얼마나 의존하는지, 친환경 산업으로 바꿀 자본·기술 능력이 얼마나 있는지 비교합니다.</p>${metricTable('energy')}</div></div><div class="field"><label>우리 국가의 정책 판단에 가장 중요한 자료 2개</label><div class="source-choice">${Object.entries(evidenceLabels).map(([k,v])=>`<label class="mini-choice ${(state.evidenceSources||[]).includes(k)?'selected':''}"><input type="checkbox" name="evidence" value="${k}" ${(state.evidenceSources||[]).includes(k)?'checked':''}>${v}</label>`).join('')}</div></div><div class="field evidence-writing" style="margin-top:14px"><label>선택한 자료에서 확인한 핵심 사실</label>${coreWritingGuide('<span>② 선택한 <strong>두 자료를 모두</strong> 활용하세요.</span><span>③ 각 자료에서 <strong>구체적인 수치를 최소 1개씩</strong> 사용하세요.</span><span>④ 단순히 수치를 나열하지 말고 <strong>왜 그 사실이 우리 국가의 정책 판단에 중요한지</strong> 설명하세요.</span>')}<div class="writing-flow"><b>생각 순서</b><span>자료 1에서 확인한 사실 → 자료 2에서 확인한 사실 → 두 사실이 우리 국가에 갖는 의미 → 필요한 정책 방향</span></div><textarea id="evidenceReason" data-min="100" data-recommended="300" maxlength="500" placeholder="선택한 두 자료의 구체적인 사실과 수치를 활용해, 그 사실이 우리 국가의 정책 판단에 어떤 의미가 있는지 직접 설명하세요.">${esc(state.evidenceReason)}</textarea>${writingCounterHtml(state.evidenceReason)}</div>`}
function renderPriority(){return `<div class="step-title"><span class="step-num">2</span><h2>우리 국가의 우선순위를 정하세요</h2></div><p class="sub">자료와 국가 카드에서 확인한 조건을 바탕으로 가장 중요한 가치 1위와 2위를 선택합니다.</p>${countryCard(false)}<div class="form-grid"><div class="field"><label>가장 중요한 가치 1위</label><select id="priority1"><option value="">선택</option>${Object.entries(priorityLabels).map(([v,l])=>`<option value="${v}" ${state.priority1===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>가장 중요한 가치 2위</label><select id="priority2"><option value="">선택</option>${Object.entries(priorityLabels).map(([v,l])=>`<option value="${v}" ${state.priority2===v?'selected':''}>${l}</option>`).join('')}</select></div></div><div class="field" style="margin-top:14px"><label>왜 이 두 가지를 중요하게 보았나요?</label>${shortWritingGuide('<span>② 앞에서 본 <strong>자료 또는 국가 조건</strong>을 최소 1가지 연결하세요.</span>')}<textarea id="priorityReason" data-min="30" data-recommended="100" maxlength="300" placeholder="앞에서 본 자료나 국가의 경제·에너지·기후 조건과 연결해 설명하세요.">${esc(state.priorityReason)}</textarea>${writingCounterHtml(state.priorityReason,30,100)}</div>`}
function renderBudget(){const sum=budgetSum();return `<div class="step-title"><span class="step-num">3</span><h2>국제기후기금 100억 원을 배분하세요</h2></div><p class="sub">공정성을 위해 모든 사업에 기본 10억 원이 배정되어 있습니다. <b>남은 50억 원</b>을 <b>5억 원 단위</b>로 추가 배분하세요.</p><div class="notice"><b>배분 규칙</b> · 총액 100억 / 모든 사업 최소 10억 / 5억 단위 조정 / 최소 한 사업 30억 이상 / 최소 한 사업은 10억 유지</div><table class="budget-table">${Object.entries(budgets).map(([k,n])=>`<tr><td><div class="budget-name">${n}</div><div class="budget-desc">${budgetDesc[k]}</div></td><td><div class="stepper"><button type="button" data-budget="${k}" data-delta="-5">−5</button><span id="amt-${k}" class="amount">${state.budget[k]}억</span><button type="button" data-budget="${k}" data-delta="5">+5</button></div></td></tr>`).join('')}</table><div id="budgetTotal" class="budget-total ${sum!==100?'bad':''}"><span>현재 배분 총액</span><span>${sum}억 / 100억 · 남은 ${Math.max(0,100-sum)}억</span></div>`}
function renderTradeoff(){const ex=budgetExtremes();const high=ex.high.map(k=>`${budgets[k]} ${state.budget[k]}억`).join(', '),low=ex.low.map(k=>`${budgets[k]} ${state.budget[k]}억`).join(', ');return `<div class="step-title"><span class="step-num">4</span><h2>예산 선택의 TRADE-OFF를 확인하세요</h2></div><p class="sub">모든 선택을 길게 설명할 필요는 없습니다. <b>무엇을 우선했고, 예산이 줄면 무엇을 포기할지</b>를 중심으로 판단합니다.</p><div class="auto-summary"><b>현재 예산</b><br>${Object.entries(state.budget).map(([k,v])=>`${budgets[k]} ${v}억`).join(' / ')}<hr class="soft-rule"><b>가장 많이 배정</b> · ${high||'-'}<br><b>가장 적게 배정</b> · ${low||'-'}</div><div class="field" style="margin-top:14px"><label>가장 많은 예산을 배정한 이유</label>${shortWritingGuide('<span>② 우리 국가의 <strong>자료 또는 우선순위</strong>와 연결하세요.</span>')}<textarea id="budgetHighReason" data-min="30" data-recommended="100" maxlength="300" placeholder="우리 국가의 자료·우선순위와 연결하여 핵심 이유를 설명하세요.">${esc(state.budgetHighReason)}</textarea>${writingCounterHtml(state.budgetHighReason,30,100)}</div><div class="decision-card" style="margin-top:14px"><div><span class="decision-kicker">추가 상황</span><h3>국제기후기금이 100억 → 70억으로 줄었습니다.</h3><p>이때 무엇을 먼저 줄이는지가 선택의 대가를 보여줍니다.</p></div><div class="form-grid"><div class="field"><label>가장 먼저 줄일 사업</label><select id="budgetCut"><option value="">선택</option>${Object.entries(budgets).map(([k,v])=>`<option value="${k}" ${state.budgetCut===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>왜 그 사업을 먼저 줄이나요?</label>${shortWritingGuide('<span>② 다른 사업과 비교해 <strong>우선순위가 낮은 이유</strong>를 밝히세요.</span>')}<textarea id="budgetCutReason" data-min="30" data-recommended="100" maxlength="300" placeholder="다른 사업보다 우선순위가 낮은 이유를 설명하세요.">${esc(state.budgetCutReason)}</textarea>${writingCounterHtml(state.budgetCutReason,30,100)}</div></div></div><div class="notice soft"><b>생각해보기</b> · 예산이 줄었을 때 무엇을 먼저 포기하는지를 보면 내가 무엇을 더 중요하게 생각했는지 알 수 있습니다.</div>`}
function renderInitialPosition(){return `<div class="step-title"><span class="step-num">5</span><h2>협상 전 국가 입장을 확정하세요</h2></div><p class="sub">협상을 시작하기 전, 우리 국가가 무엇을 중요하게 생각하고 어떤 방향의 기후정책을 원하는지 정리합니다.</p><div class="auto-summary"><b>내 선택 요약</b><br>국가: ${countryLabels[session.country]}<br>우선순위: ${priorityLabels[state.priority1]||'-'} → ${priorityLabels[state.priority2]||'-'}<br>예산: ${Object.entries(state.budget).map(([k,v])=>`${budgets[k]} ${v}억`).join(' / ')}</div><div class="field" style="margin-top:16px"><label>협상 전 초기 입장</label>${coreWritingGuide('<span>② 우리 국가의 <strong>핵심 목표</strong>와 그 이유를 국가 조건에 연결하세요.</span><span>③ 국제사회에 요구하거나 제안할 <strong>정책 방향</strong>이 드러나게 작성하세요.</span>')}<textarea id="initialPosition" data-min="100" data-recommended="300" maxlength="500" style="min-height:150px" placeholder="우리 국가가 중요하게 생각하는 목표, 그 이유, 국제사회에 요구하거나 제안할 정책 방향을 직접 작성하세요.">${esc(state.initialPosition)}</textarea>${writingCounterHtml(state.initialPosition)}</div><div class="notice soft">이 답안은 마지막 재판단 단계에서 다시 보여드립니다. 협상 후 내 생각이 유지되었는지, 바뀌었는지를 비교하게 됩니다.</div>`}
function renderAgreement(){return `<div class="step-title"><span class="step-num">6</span><h2>새로운 국제기후협약을 선택하세요</h2></div><p class="sub">이제 우리 국가만의 이익이 아니라 다른 국가들과 함께 적용할 국제규칙을 선택합니다.</p>${[['A','동일책임안','모든 국가는 2040년까지 온실가스를 40% 감축한다.','명확하고 강력하지만 국가별 과거 책임과 발전 수준 차이를 충분히 반영하지 못한다.'],['B','차등책임안','선진국 50%, 개발도상국 25% 감축. 선진국은 기술과 자금을 지원한다.','과거 책임과 능력 차이를 고려하지만 선진국의 부담이 커지고 국가 분류를 둘러싼 갈등이 생길 수 있다.'],['C','자율감축안','각 국가는 경제 상황에 따라 스스로 감축 목표를 결정한다.','국가별 상황을 반영하기 쉽지만 전체 감축 수준이 낮아질 위험이 있다.']].map(([v,t,body,small])=>`<label class="agreement ${state.agreement===v?'selected':''}"><input type="radio" name="agreement" value="${v}" ${state.agreement===v?'checked':''}><strong>${v}안 · ${t}</strong><div>${body}</div><small>${small}</small></label>`).join('')}<div class="field"><label>이 협약을 선택한 이유</label>${shortWritingGuide('<span>② 우리 국가의 조건과 <strong>국제협력 가능성</strong>을 함께 고려하세요.</span>')}<textarea id="agreementReason" data-min="30" data-recommended="100" maxlength="300" placeholder="우리 국가의 조건과 다른 국가와의 협력 가능성을 함께 고려해 설명하세요.">${esc(state.agreementReason)}</textarea>${writingCounterHtml(state.agreementReason,30,100)}</div><div class="form-grid" style="margin-top:14px"><div class="field"><label>우리 국가에 가장 불리한 협약</label><select id="unfavorableAgreement"><option value="">선택</option>${['A','B','C'].map(v=>`<option value="${v}" ${state.unfavorableAgreement===v?'selected':''}>${agreementLabels[v]}</option>`).join('')}</select></div><div class="field"><label>왜 불리한가요?</label>${shortWritingGuide('<span>② 우리 국가가 부담하게 될 <strong>구체적인 불이익</strong>을 설명하세요.</span>')}<textarea id="unfavorableReason" data-min="30" data-recommended="100" maxlength="300" placeholder="우리 국가의 경제·에너지·기후 조건과 연결해 불리한 이유를 설명하세요.">${esc(state.unfavorableReason)}</textarea>${writingCounterHtml(state.unfavorableReason,30,100)}</div></div>`}
function compactCountry(k,c){return `<div class="opponent-card ${state.opposingCountry===k?'selected':''}" data-country-card="${k}"><h3>${c.name}</h3><span class="tag">${c.type}</span><ul>${c.facts.slice(0,3).map(x=>`<li>${x}</li>`).join('')}</ul><div class="mini-metrics"><span>배출책임 ${c.metrics.past}</span><span>피해위험 ${c.metrics.damage}</span><span>화석의존 ${c.metrics.fossil}</span></div></div>`}
function renderOpposition(){return `<div class="step-title"><span class="step-num">7</span><h2>누가 왜 반대할지 분석하세요</h2></div><p class="sub">다른 국가의 정보를 다시 확인한 뒤, 우리 국가의 정책과 가장 크게 충돌할 국가를 찾습니다.</p><div class="opponent-grid">${Object.entries(countryData).filter(([k])=>k!==session.country).map(([k,c])=>compactCountry(k,c)).join('')}</div><div class="field" style="margin-top:16px"><label>반대할 가능성이 가장 높은 국가</label><select id="opposingCountry"><option value="">선택</option>${Object.entries(countryLabels).filter(([k])=>k!==session.country).map(([k,v])=>`<option value="${k}" ${state.opposingCountry===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field" style="margin-top:14px"><label>그 국가는 왜 반대할까요?</label>${shortWritingGuide('<span>② 상대 국가의 <strong>산업·에너지·피해 조건</strong>을 최소 1개 근거로 사용하세요.</span>')}<textarea id="oppositionReason" data-min="30" data-recommended="100" maxlength="300" placeholder="상대 국가의 산업·에너지·피해 조건을 근거로 반대 이유를 설명하세요.">${esc(state.oppositionReason)}</textarea>${writingCounterHtml(state.oppositionReason,30,100)}</div>`}
function renderCompromise(){return `<div class="step-title"><span class="step-num">8</span><h2>갈등을 줄일 절충안을 만드세요</h2></div><p class="sub">우리 국가가 원하는 것을 모두 얻을 수는 없습니다. 상대 국가도 받아들일 수 있도록 협약의 한 부분을 조정합니다.</p><div class="conflict-box"><b>현재 충돌 다시 보기</b><br><b>우리 국가</b> · ${countryLabels[session.country]} · 우선순위 ${priorityLabels[state.priority1]||'-'} → ${priorityLabels[state.priority2]||'-'} · 지지 협약 ${agreementLabels[state.agreement]||'-'}<br><br><b>상대 국가</b> · ${countryLabels[state.opposingCountry]||'-'}${state.opposingCountry?`<br>${countryData[state.opposingCountry].facts.slice(0,3).map(x=>`• ${x}`).join('<br>')}`:''}<br><br><b>내가 앞에서 판단한 반대 이유</b><br>${esc(state.oppositionReason||'-')}</div><div class="field"><label>가장 먼저 조정할 부분</label><select id="compromiseDimension"><option value="">선택</option><option value="target" ${state.compromiseDimension==='target'?'selected':''}>온실가스 감축률</option><option value="money" ${state.compromiseDimension==='money'?'selected':''}>기후재정 지원 규모</option><option value="schedule" ${state.compromiseDimension==='schedule'?'selected':''}>이행 시기</option><option value="technology" ${state.compromiseDimension==='technology'?'selected':''}>기술 이전·지원</option><option value="review" ${state.compromiseDimension==='review'?'selected':''}>국가별 주기적 재검토</option></select></div><div class="field" style="margin-top:14px"><label>양쪽이 모두 받아들일 수 있는 절충안</label>${coreWritingGuide('<span>② <strong>우리 국가가 양보하거나 조정할 부분</strong>을 분명히 하세요.</span><span>③ <strong>상대 국가가 얻거나 받아들일 수 있는 부분</strong>도 함께 제시하세요.</span>')}<textarea id="compromise" data-min="100" data-recommended="300" maxlength="500" style="min-height:150px" placeholder="우리 국가와 상대 국가가 각각 무엇을 조정하고 무엇을 얻는지 드러나도록 구체적인 절충안을 작성하세요.">${esc(state.compromise)}</textarea>${writingCounterHtml(state.compromise)}</div>`}
function renderActors(){const selected=(state.actors||[]);return `<div class="step-title"><span class="step-num">9</span><h2>국제협력을 실행할 주체를 설계하세요</h2></div><p class="sub">주체 2개를 선택한 뒤, <b>서로 다른 역할</b>을 맡겨 협력 구조를 완성합니다. 긴 설명보다 역할 구분이 중요합니다.</p><div class="actor-grid">${Object.entries(actorData).map(([k,v])=>`<label class="actor ${selected.includes(k)?'selected':''}"><input type="checkbox" name="actor" value="${k}" ${selected.includes(k)?'checked':''}><b>${v.name}</b><small>${v.role}</small></label>`).join('')}</div>${selected.length===2?`<div class="role-assignment-grid">${selected.map((k,i)=>`<div class="role-assignment"><span>협력 주체 ${i+1}</span><h3>${actorLabels[k]}</h3><div class="field"><label>이 주체가 맡을 핵심 역할</label><select data-actor-role="${k}"><option value="">역할 선택</option>${(actorAllowedRoles[k]||[]).map(rv=>`<option value="${rv}" ${state.actorAssignments?.[k]===rv?'selected':''}>${actorRoleOptions[rv]}</option>`).join('')}</select></div></div>`).join('')}</div><div class="field" style="margin-top:14px"><label>왜 이 두 주체가 함께 필요할까요?</label>${shortWritingGuide('<span>② 두 주체가 맡은 <strong>서로 다른 역할이 어떻게 연결되는지</strong> 설명하세요.</span>')}<textarea id="actorReason" data-min="30" data-recommended="100" maxlength="300" placeholder="각자 다른 역할을 맡아야 하는 이유와 서로 어떻게 협력하는지 설명하세요.">${esc(state.actorReason)}</textarea>${writingCounterHtml(state.actorReason,30,100)}</div>`:`<div class="notice soft" style="margin-top:14px">먼저 서로 협력할 주체를 정확히 2개 선택하세요.</div>`}`}
function renderFinal(){const roleSummary=(state.actors||[]).map(k=>`${actorLabels[k]}(${actorRoleOptions[state.actorAssignments?.[k]]||'역할 미정'})`).join(' · ');return `<div class="step-title"><span class="step-num">10</span><h2>협상 후 최종 합의문을 작성하세요</h2></div><p class="sub">앞에서 쓴 내용을 그대로 반복하지 않고, <b>협상을 통해 새롭게 고려한 점과 최종적으로 선택한 방향</b>을 중심으로 마무리합니다.</p><div class="compare-grid"><div class="compare-card"><span>협상 전 초기 입장</span><p>${esc(state.initialPosition||'-')}</p></div><div class="compare-card"><span>협상 결과 요약</span><p>지지 협약: ${agreementLabels[state.agreement]||'-'}<br>충돌 국가: ${countryLabels[state.opposingCountry]||'-'}<br>절충 요소: ${compromiseLabel(state.compromiseDimension)}<br>협력 구조: ${esc(roleSummary||'-')}</p></div></div><div class="field"><label>협상 후 나의 판단</label><div class="source-choice two"><label class="mini-choice ${state.reconsiderChoice==='maintain'?'selected':''}"><input type="radio" name="reconsiderChoice" value="maintain" ${state.reconsiderChoice==='maintain'?'checked':''}>핵심 입장을 유지했다</label><label class="mini-choice ${state.reconsiderChoice==='revise'?'selected':''}"><input type="radio" name="reconsiderChoice" value="revise" ${state.reconsiderChoice==='revise'?'checked':''}>일부 또는 전체 입장을 수정했다</label></div></div><div class="field" style="margin-top:16px"><label>최종 정책 합의문</label>${coreWritingGuide('<span>② 협상 과정에서 <strong>새롭게 고려한 점</strong>을 포함하세요.</span><span>③ 유지하거나 수정한 <strong>최종 정책 방향</strong>과 상대국과의 <strong>절충·협력</strong>을 함께 제시하세요.</span>')}<textarea id="finalDeclaration" data-min="100" data-recommended="300" maxlength="600" style="min-height:160px" placeholder="협상 전과 비교해 새롭게 고려한 점, 최종 정책 방향, 상대국과 함께 실행할 절충·협력 방안을 직접 작성하세요.">${esc(state.finalDeclaration)}</textarea>${writingCounterHtml(state.finalDeclaration)}</div><div class="notice soft"><b>다음은 최종 검토입니다.</b> · 이 단계 작성이 끝나면 전체 제출 내용을 한 화면에서 다시 확인하고, 필요한 부분을 수정한 뒤 최종 제출할 수 있습니다.</div>`}
function renderFastCountry(){const c=countryData[session.country];return `<div class="step-title"><span class="step-num">1</span><h2>우리 국가와 처음 판단</h2></div><p class="sub">국가 조건을 읽고 지금 가장 중요하다고 생각하는 가치 하나를 고르세요.</p><div class="country-card"><div><span class="tag">${c.type}</span><h2>${c.name}</h2><p>${c.dilemma}</p></div><ul>${c.facts.slice(0,3).map(x=>`<li>${x}</li>`).join('')}</ul></div><div class="field"><label>가장 중요한 가치</label><p class="choice-help">다섯 가지를 비교한 뒤 카드 하나를 선택하세요.</p><div class="priority-choice-grid">${Object.entries(priorityLabels).map(([v,l])=>`<label class="priority-choice ${state.priority1===v?'selected':''}"><input type="radio" name="priority1" value="${v}" ${state.priority1===v?'checked':''}><span class="priority-radio"></span><strong>${l}</strong><small>${priorityHints[v]}</small></label>`).join('')}</div></div><div class="field" style="margin-top:14px"><label>그렇게 생각한 이유</label><textarea id="priorityReason" data-min="20" data-recommended="60" maxlength="180" placeholder="국가 조건 한 가지와 연결해 짧게 쓰세요.">${esc(state.priorityReason)}</textarea>${writingCounterHtml(state.priorityReason,20,60)}</div>`}
function renderFastDilemma(){const total=budgetSum();return `<div class="step-title"><span class="step-num">2</span><h2>협약을 고르고 100억 원을 직접 배분하세요</h2></div><div class="story-bridge"><span>회의 속보</span><h3>각국 대표에게 공동 기후기금 100억 원의 사용 계획을 제출하라는 요청이 왔습니다.</h3><p>${countryData[session.country].name}은 “${countryData[session.country].dilemma}”라는 과제를 안고 있습니다. 1단계에서 선택한 가치인 <b>${priorityLabels[state.priority1]||'우리 국가의 우선 가치'}</b>를 실제 정책과 예산으로 보여주세요.</p></div><div class="field"><label>먼저 국제기후협약을 선택하세요</label><p class="choice-help">이 협약은 모든 국가가 지킬 기본 규칙입니다.</p>${[['A','동일책임안','모든 국가가 같은 감축 목표를 지킵니다.'],['B','차등책임안','책임과 능력이 큰 국가가 더 감축하고 지원합니다.'],['C','자율감축안','각 국가가 형편에 맞게 목표를 정합니다.']].map(([v,t,body])=>`<label class="agreement ${state.agreement===v?'selected':''}"><input type="radio" name="agreement" value="${v}" ${state.agreement===v?'checked':''}><strong>${v}안 · ${t}</strong><div>${body}</div></label>`).join('')}</div><div class="field budget-allocation" style="margin-top:18px"><label>공동 기후기금 100억 원 직접 배분</label><p class="choice-help">각 항목의 ＋·－ 버튼으로 10억 원씩 조절하세요. 다섯 항목의 합계가 정확히 100억 원이어야 합니다.</p><div class="budget-story-note">내 국가에 필요한 사업만 생각하지 말고, 다른 국가도 합의할 수 있는 배분인지 함께 고려하세요.</div><div class="direct-budget-list">${Object.entries(budgets).map(([k,name])=>`<div class="direct-budget-row"><div><b>${name}</b><small>${budgetDesc[k]}</small></div><div class="stepper"><button type="button" data-budget="${k}" data-delta="-10" aria-label="${name} 10억 줄이기">−</button><span class="amount">${state.budget[k]||0}억</span><button type="button" data-budget="${k}" data-delta="10" aria-label="${name} 10억 늘리기">＋</button></div></div>`).join('')}</div><div class="budget-total ${total===100?'':'bad'}"><span>현재 배분 합계</span><b>${total}억 / 100억</b></div></div><div class="field" style="margin-top:14px"><label>협약과 예산을 이렇게 정한 이유</label><textarea id="agreementReason" data-min="30" data-recommended="80" maxlength="220" placeholder="우리 국가의 조건과 가장 많이 배정한 사업을 연결해 설명하세요.">${esc(state.agreementReason)}</textarea>${writingCounterHtml(state.agreementReason,30,80)}</div>`}
function renderFastCompromise(){const selected=state.opposingCountry||'',c=countryData[selected],others=Object.entries(countryData).filter(([k])=>k!==session.country);return `<div class="step-title"><span class="step-num">3</span><h2>상대국과 절충하기</h2></div><p class="sub">다른 세 국가 중 협상할 상대국을 직접 고른 뒤, 서로 받아들일 수 있는 절충안을 만드세요.</p><div class="field"><label>협상할 상대국 선택</label><p class="choice-help">내 국가와 조건이 다른 나라를 비교하고 한 곳을 선택하세요.</p><div class="opponent-choice-grid">${others.map(([k,n])=>`<label class="opponent-choice ${selected===k?'selected':''}"><input type="radio" name="opposingCountry" value="${k}" ${selected===k?'checked':''}><strong>${n.name}</strong><span>${n.type}</span><small>${n.dilemma}</small></label>`).join('')}</div></div>${c?`<div class="conflict-box selected-opponent"><b>선택한 상대국 · ${c.name}</b><br>${c.facts.slice(0,2).map(x=>`• ${x}`).join('<br>')}</div>`:'<div class="notice soft">상대국을 선택하면 이곳에 상대국의 핵심 조건이 표시됩니다.</div>'}<div class="field"><label>먼저 조정할 부분</label><p class="choice-help">협상에서 가장 먼저 맞춰야 할 쟁점을 하나 선택하세요.</p><div class="dimension-choice-grid">${[['target','감축 목표','얼마나 줄일지'],['money','기후재정 지원','누가 얼마를 지원할지'],['schedule','이행 시기','언제부터 실행할지'],['technology','기술 지원','어떤 기술을 나눌지']].map(([v,t,d])=>`<label class="dimension-choice ${state.compromiseDimension===v?'selected':''}"><input type="radio" name="compromiseDimension" value="${v}" ${state.compromiseDimension===v?'checked':''}><strong>${t}</strong><small>${d}</small></label>`).join('')}</div></div><div class="field" style="margin-top:14px"><label>절충 방식</label><div class="source-choice"><label class="mini-choice ${state.compromiseChoice==='gradual'?'selected':''}"><input type="radio" name="compromiseChoice" value="gradual" ${state.compromiseChoice==='gradual'?'checked':''}>목표는 유지하고 시기를 나눈다</label><label class="mini-choice ${state.compromiseChoice==='support'?'selected':''}"><input type="radio" name="compromiseChoice" value="support" ${state.compromiseChoice==='support'?'checked':''}>더 감축하는 대신 돈·기술을 지원한다</label><label class="mini-choice ${state.compromiseChoice==='review'?'selected':''}"><input type="radio" name="compromiseChoice" value="review" ${state.compromiseChoice==='review'?'checked':''}>각자 목표를 정하고 5년마다 높인다</label></div></div><div class="field" style="margin-top:14px"><label>우리 국가와 상대국이 합의할 내용</label><textarea id="compromise" data-min="30" data-recommended="80" maxlength="220" placeholder="누가 무엇을 하고 무엇을 지원받는지 한두 문장으로 쓰세요.">${esc(state.compromise)}</textarea>${writingCounterHtml(state.compromise,30,80)}</div>`}
function objectParticle(word){const last=String(word||'').charCodeAt(String(word||'').length-1),hasFinal=last>=0xAC00&&last<=0xD7A3&&(last-0xAC00)%28!==0;return `${word}${hasFinal?'을':'를'}`}
function initialJudgmentText(){const value=priorityLabels[state.priority1]||'선택한 가치';const reason=String(state.priorityReason||'').trim();return `우리 국가는 ${objectParticle(value)} 가장 중요한 가치로 판단했다.${reason?' '+reason:''}`}
function chosenOpponent(){return state.opposingCountry||opponentByCountry[session.country]}
function renderFastReflection(){const opp=chosenOpponent();return `<div class="step-title"><span class="step-num">4</span><h2>판단 변화와 최종 합의</h2></div><p class="sub">처음 생각과 협상 결과를 비교하고 최종 결론을 짧게 작성하세요.</p><div class="compare-grid"><div class="compare-card"><span>처음 판단</span><p>${esc(initialJudgmentText())}</p></div><div class="compare-card"><span>협상 결과</span><p>${agreementLabels[state.agreement]||'-'}<br>${budgetSummary()}<br>${countryLabels[opp]}과 절충: ${esc(state.compromise||'-')}</p></div></div><div class="field"><label>협상 후 판단</label><div class="source-choice two"><label class="mini-choice ${state.reconsiderChoice==='maintain'?'selected':''}"><input type="radio" name="reconsiderChoice" value="maintain" ${state.reconsiderChoice==='maintain'?'checked':''}>처음 판단을 유지했다</label><label class="mini-choice ${state.reconsiderChoice==='revise'?'selected':''}"><input type="radio" name="reconsiderChoice" value="revise" ${state.reconsiderChoice==='revise'?'checked':''}>일부 판단을 바꾸었다</label></div></div><div class="field" style="margin-top:16px"><label>최종 기후 합의문</label><textarea id="finalDeclaration" data-min="60" data-recommended="120" maxlength="300" placeholder="우리 국가는 ○○을 하되, 상대국에는 ○○을 지원하여 함께 ○○하겠습니다.">${esc(state.finalDeclaration)}</textarea>${writingCounterHtml(state.finalDeclaration,60,120)}</div><div class="notice soft">작성 후 다음 버튼을 누르면 전체 내용을 확인하고 제출할 수 있습니다.</div>`}
function decisionSummaryHtml(){
 if(!session)return '<p>아직 수행평가를 시작하지 않았습니다.</p>';
 const opp=chosenOpponent();
 return `<div class="decision-summary-grid">
   <div><span>내 국가</span><b>${countryLabels[session.country]}</b></div>
   <div><span>처음 판단</span><b>${priorityLabels[state.priority1]||'-'}</b></div>
   <div><span>100억 배분</span><b>${budgetSummary()}</b></div>
   <div><span>지지 협약</span><b>${agreementLabels[state.agreement]||'-'}</b></div>
   <div><span>상대국</span><b>${countryLabels[opp]||'-'}</b></div>
   <div><span>절충안</span><b>${esc(state.compromise||'-')}</b></div>
   <div><span>최종 합의</span><b>${esc(state.finalDeclaration||'-')}</b></div>
 </div>`;
}
function openModal(id){const el=document.getElementById(id);if(!el)return;if(id==='decisionModal')document.getElementById('decisionSummary').innerHTML=decisionSummaryHtml();el.classList.remove('hidden');el.setAttribute('aria-hidden','false')}
function closeModal(id){const el=document.getElementById(id);if(!el)return;el.classList.add('hidden');el.setAttribute('aria-hidden','true')}

function compromiseLabel(v){return ({target:'온실가스 감축률',money:'기후재정 지원 규모',schedule:'이행 시기',technology:'기술 이전·지원',review:'국가별 주기적 재검토'})[v]||'-'}
function bindStep(){
 document.querySelectorAll('textarea').forEach(el=>el.addEventListener('input',()=>{count(el);debouncedSave()}));
 document.querySelectorAll('select,input[type="radio"]').forEach(el=>el.addEventListener('change',()=>debouncedSave()));
 document.querySelectorAll('input[name="opposingCountry"]').forEach(input=>input.addEventListener('change',()=>{state.opposingCountry=input.value;render();debouncedSave()}));
 document.querySelectorAll('input[name="evidence"]').forEach(input=>input.addEventListener('change',e=>{const v=input.value;state.evidenceSources=state.evidenceSources||[];if(input.checked){if(state.evidenceSources.length>=2){input.checked=false;return toast('중요 자료는 2개만 선택할 수 있습니다.')}state.evidenceSources.push(v)}else state.evidenceSources=state.evidenceSources.filter(x=>x!==v);render()}));
 document.querySelectorAll('[data-budget]').forEach(btn=>btn.addEventListener('click',()=>{const k=btn.dataset.budget,d=Number(btn.dataset.delta),sum=budgetSum(),next=Number(state.budget[k]||0)+d;if(next<0||next>100)return;if(d>0&&sum>=100)return toast('총 100억 원을 모두 배분했습니다.');state.budget[k]=next;state.budgetTouched=true;render();debouncedSave()}));
 document.querySelectorAll('.actor').forEach(l=>l.addEventListener('click',e=>{e.preventDefault();const input=l.querySelector('input'),v=input.value;state.actors=state.actors||[];state.actorAssignments=state.actorAssignments||{};if(state.actors.includes(v)){state.actors=state.actors.filter(x=>x!==v);delete state.actorAssignments[v]}else if(state.actors.length<2)state.actors.push(v);else return toast('협력 주체는 2개만 선택할 수 있습니다.');render();debouncedSave()}));
 document.querySelectorAll('[data-actor-role]').forEach(sel=>sel.addEventListener('change',()=>{state.actorAssignments=state.actorAssignments||{};state.actorAssignments[sel.dataset.actorRole]=sel.value;debouncedSave()}));
 document.querySelectorAll('[data-country-card]').forEach(card=>card.addEventListener('click',()=>{state.opposingCountry=card.dataset.countryCard;render();debouncedSave()}));
}
function collect(){if($('#assessment')?.classList.contains('hidden'))return;const v=id=>document.querySelector(id)?.value?.trim();
 if(step===0){state.priority1=document.querySelector('input[name="priority1"]:checked')?.value||'';state.priority2='';state.priorityReason=v('#priorityReason');state.initialPosition=initialJudgmentText()}
 if(step===1){state.agreement=document.querySelector('input[name="agreement"]:checked')?.value||'';state.budgetPlan='custom';state.agreementReason=v('#agreementReason');state.budgetHighReason=state.agreementReason}
 if(step===2){state.opposingCountry=document.querySelector('input[name="opposingCountry"]:checked')?.value||state.opposingCountry||'';state.oppositionReason=countryData[state.opposingCountry]?.dilemma||'';state.compromiseDimension=document.querySelector('input[name="compromiseDimension"]:checked')?.value||'';state.compromiseChoice=document.querySelector('input[name="compromiseChoice"]:checked')?.value||'';state.compromise=v('#compromise')}
 if(step===3){state.reconsiderChoice=document.querySelector('input[name="reconsiderChoice"]:checked')?.value||'';state.finalDeclaration=v('#finalDeclaration')}
 state.assessmentVersion='45min-v3.6.0';
}
function budgetSum(){return Object.values(state.budget||{}).reduce((a,b)=>a+Number(b||0),0)}
function budgetSummary(){return Object.entries(state.budget||{}).map(([k,v])=>`${budgets[k]} ${Number(v||0)}억`).join(' · ')}
function budgetExtremes(){const es=Object.entries(state.budget||{});if(!es.length)return{high:[],low:[]};const max=Math.max(...es.map(x=>x[1])),min=Math.min(...es.map(x=>x[1]));return{high:es.filter(x=>x[1]===max).map(x=>x[0]),low:es.filter(x=>x[1]===min).map(x=>x[0])}}
function validate(){collect();
 if(step===0){if(!state.priority1)return'가장 중요한 가치를 선택하세요.';const e=answerError(state.priorityReason,20,'판단 이유를 다시 확인하세요.');if(e)return e+' 국가 조건 한 가지와 연결하면 됩니다.'}
 if(step===1){if(!state.agreement)return'국제기후협약을 하나 선택하세요.';if(!state.budgetTouched)return'＋ 버튼을 눌러 100억 원을 직접 배분하세요.';if(budgetSum()!==100)return`현재 ${budgetSum()}억 원입니다. 다섯 사업의 합계를 정확히 100억 원으로 맞추세요.`;const e=answerError(state.agreementReason,30,'협약과 예산 배분 이유를 다시 확인하세요.');if(e)return e}
 if(step===2){if(!state.opposingCountry)return'협상할 상대국을 선택하세요.';if(!state.compromiseDimension)return'먼저 조정할 부분을 선택하세요.';if(!state.compromiseChoice)return'절충 방식을 하나 선택하세요.';const e=answerError(state.compromise,30,'합의 내용을 다시 확인하세요.');if(e)return e+' 양쪽이 무엇을 하고 얻는지 포함하세요.'}
 if(step===3){if(!state.reconsiderChoice)return'처음 판단을 유지했는지 바꾸었는지 선택하세요.';const e=answerError(state.finalDeclaration,60,'최종 합의문을 다시 확인하세요.');if(e)return e}
 return'';
}
function setSaveStatus(kind,text){const el=$('#saveStatus'),btn=$('#saveBtn');if(el){el.className=`save-status ${kind||''}`.trim();el.textContent=text}if(btn){btn.disabled=kind==='saving'||kind==='queued';btn.textContent=kind==='saving'||kind==='queued'?'저장 중…':'임시 저장'}}
async function runSaveWorker(){let ok=true,lastError='';setSaveStatus('saving','저장 중… 화면을 그대로 두세요.');while(pendingSave){const job=pendingSave;pendingSave=null;try{const r=await fetch('/api/save',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(job.payload)});const j=await r.json().catch(()=>({}));if(!r.ok)throw new Error(j.error||'저장 요청에 실패했습니다.');if(job.show)toast('저장 완료');if(pendingSave)setSaveStatus('queued','새 변경사항을 이어서 저장 중…')}catch(e){ok=false;lastError=e.message||'인터넷 연결을 확인하세요.';pendingSave=null;break}}if(ok)setSaveStatus('saved',`저장 완료 · ${new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'})}`);else setSaveStatus('error',`저장 실패 · ${lastError}`);const waiters=saveWaiters.splice(0);saveWorker=null;waiters.forEach(resolve=>resolve(ok));return ok}
async function save(show=true){if(!session)return false;collect();state.currentStep=step;const snapshot=JSON.parse(JSON.stringify(state));pendingSave={show:show||pendingSave?.show,payload:{sessionId:session.sessionId,data:snapshot,progress:stepProgress[step]||0}};const result=new Promise(resolve=>saveWaiters.push(resolve));if(saveWorker)setSaveStatus('queued','변경사항을 모아 저장 중…');else saveWorker=runSaveWorker();return result}
function debouncedSave(){clearTimeout(saveTimer);saveTimer=setTimeout(()=>save(false),900)}
async function goNext(){if(navigationLocked)return;const err=validate();if(err){message(err);return}navigationLocked=true;const next=$('#nextBtn'),prev=$('#prevBtn');if(next){next.disabled=true;next.textContent='저장 후 이동 중…'}if(prev)prev.disabled=true;try{message('');if(!await save(false)){message('저장하지 못했습니다. 인터넷 연결을 확인한 뒤 다시 눌러 주세요.');return}if(step<3){step++;state.currentStep=step;if(!await save(false)){step--;state.currentStep=step;message('다음 단계 위치를 저장하지 못했습니다. 다시 눌러 주세요.');return}render();window.scrollTo({top:0,behavior:'smooth'})}else{state.reviewReady=true;if(!await save(false)){message('최종 검토 상태를 저장하지 못했습니다. 다시 눌러 주세요.');return}showFinalReview();window.scrollTo({top:0,behavior:'smooth'})}}finally{navigationLocked=false;if(next){next.disabled=false;next.textContent='다음 단계 →'}if(prev)prev.disabled=false}}

function finalReviewSection(title,body,editStep,editable=true){return `<article class="final-review-card"><div class="final-review-card-head"><h3>${title}</h3>${editable?`<button type="button" class="review-edit-btn" data-edit-step="${editStep}">수정하기</button>`:''}</div><div class="final-review-content">${body}</div></article>`}
function finalReviewSummaryHtml(editable=true){
 const opp=chosenOpponent();
 return `<div class="final-review-country"><span>내 국가</span><b>${countryLabels[session.country]}</b><small>${countryData[session.country].dilemma}</small></div><div class="final-review-grid">
 ${finalReviewSection('1. 국가와 처음 판단',`<p>${esc(initialJudgmentText())}</p>`,0,editable)}
 ${finalReviewSection('2. 협약과 100억 배분',`<b>${agreementLabels[state.agreement]||'-'}</b><p>${budgetSummary()}</p><p>${esc(state.agreementReason||'-')}</p>`,1,editable)}
 ${finalReviewSection('3. 상대국과 절충',`<b>${countryLabels[opp]||'-'} · ${compromiseLabel(state.compromiseDimension)}</b><p>${esc(state.compromise||'-')}</p>`,2,editable)}
 ${finalReviewSection('4. 최종 판단과 합의문',`<b>${state.reconsiderChoice==='revise'?'일부 판단을 수정':'처음 판단을 유지'}</b><p>${esc(state.finalDeclaration||'-')}</p>`,3,editable)}
 </div>`;
}
function showFinalReview(){collect();reviewEditStep=null;$('#assessment').classList.add('hidden');$('#countryAssign').classList.add('hidden');$('#finalReview').classList.remove('hidden');$('#progress').style.width='98%';$('#lessonPill').textContent='최종 제출 전 검토';$('#finalReviewSummary').innerHTML=finalReviewSummaryHtml(true);document.querySelectorAll('.review-edit-btn').forEach(btn=>btn.addEventListener('click',()=>editFromReview(Number(btn.dataset.editStep))));}
async function editFromReview(targetStep){reviewEditStep=targetStep;step=targetStep;state.currentStep=step;await save(false);$('#finalReview').classList.add('hidden');showAssessment();render();window.scrollTo({top:0,behavior:'smooth'})}
function ensureReviewReturnButton(){let btn=document.getElementById('returnReviewBtn');if(reviewEditStep===null){btn?.remove();return}if(!btn){btn=document.createElement('button');btn.id='returnReviewBtn';btn.className='secondary';btn.textContent='최종 검토로 돌아가기';document.querySelector('#assessment .actions .right')?.prepend(btn)}btn.onclick=async()=>{const err=validate();if(err){message(err);return}collect();await save(false);reviewEditStep=null;showFinalReview();window.scrollTo({top:0,behavior:'smooth'})}}

async function finalSubmit(auto=false){if(submitLocked)return;collect();if(!auto&& !confirm('이 내용으로 최종 제출하시겠습니까? 제출 후에는 학생 화면에서 수정할 수 없습니다.'))return;submitLocked=true;const btn=$('#confirmFinalSubmitBtn');if(btn){btn.disabled=true;btn.textContent='저장 후 제출 중…'}try{if(!auto&&!await save(false))throw new Error('최신 답안을 저장하지 못했습니다. 인터넷 연결을 확인한 뒤 다시 제출하세요.');const r=await fetch('/api/submit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({sessionId:session.sessionId,data:state})});const j=await r.json();if(!r.ok)throw new Error(j.error||'제출 실패');clearInterval(timerHandle);clearInterval(timerSyncHandle);$('#assessment').classList.add('hidden');$('#finalReview').classList.add('hidden');$('#done').classList.remove('hidden');$('#progress').style.width='100%';$('#timer').classList.add('hidden');$('#doneInfo').innerHTML=`<b>${esc(session.studentId)} ${esc(session.name)}</b> · ${countryLabels[session.country]}<br>${auto?'45분 제한 시간이 종료되어 현재까지 작성한 내용이 자동 제출되었습니다.':'최종 제출이 정상적으로 완료되었습니다.'}`;$('#doneSummary').innerHTML=finalReviewSummaryHtml(false);}catch(e){alert(e.message)}finally{submitLocked=false;if(btn){btn.disabled=false;btn.textContent='이 내용으로 최종 제출 →'}}}

$('#startBtn').addEventListener('click',startAssessment);
$('#studentId').addEventListener('input',()=>applyServerGate(serverOpen));
$('#studentId').addEventListener('keydown',e=>{if(e.key==='Enter'&&isTeacherEntry()){e.preventDefault();startAssessment()}});
$('#spinCountryBtn').addEventListener('click',spinCountryRoulette);
$('#beginAssignedBtn').addEventListener('click',beginAssignedAssessment);
$('#nextBtn').addEventListener('click',goNext);
$('#prevBtn').addEventListener('click',async()=>{collect();await save(false);if(step>0){step--;state.currentStep=step;render();window.scrollTo({top:0,behavior:'smooth'})}});
$('#saveBtn').addEventListener('click',()=>save(true));
$('#reviewBackBtn').addEventListener('click',async()=>{reviewEditStep=3;step=3;state.currentStep=3;await save(false);$('#finalReview').classList.add('hidden');showAssessment();render();window.scrollTo({top:0,behavior:'smooth'})});
$('#confirmFinalSubmitBtn').addEventListener('click',()=>finalSubmit(false));


$('#decisionReviewBtn').addEventListener('click',()=>{collect();openModal('decisionModal')});
$('#glossaryBtn').addEventListener('click',()=>openModal('glossaryModal'));
function openCountryHelp(mode){if(!session)return;document.getElementById('countryGuideBody').innerHTML=mode==='mine'?countryCard(true):allCountryOverview();openModal('countryGuideModal')}
$('#countryGuideBtn').addEventListener('click',()=>openCountryHelp('all'));
$('#myCountryQuickBtn').addEventListener('click',()=>openCountryHelp('mine'));
$('#compareCountriesQuickBtn').addEventListener('click',()=>openCountryHelp('all'));
$('#waitingCountryGuideBtn').addEventListener('click',()=>openCountryHelp('all'));
document.querySelectorAll('[data-close-modal]').forEach(el=>el.addEventListener('click',()=>closeModal(el.dataset.closeModal)));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeModal('decisionModal');closeModal('glossaryModal');closeModal('countryGuideModal')}});
window.addEventListener('beforeunload',e=>{if(saveWorker||pendingSave){e.preventDefault();e.returnValue=''}});

